import { bulkhead, wrap, timeout, retry, handleAll, BulkheadRejectedError } from 'cockatiel';

const dbPolicy = wrap(
  retry(handleAll, { maxAttempts: 2 }),
  timeout(500),
  bulkhead(8, 16),                 // 8 concurrent, 16 queued
);

try { return await dbPolicy.execute(() => db.query<Row>(sql)); }
catch (e) { if (e instanceof BulkheadRejectedError) return busy(); throw e; }

import pLimit, { type LimitFunction } from 'p-limit';

const dbLimit: LimitFunction = pLimit(8);   // one per dependency

export async function query(sql: string): Promise<Row[]> {
  if (dbLimit.pendingCount > 64) throw new BulkheadFull();
  return dbLimit(() => db.query<Row>(sql));
}

